// Package store is the app's storage contract: the API handlers and the
// feature cards talk to a Store, never to a database driver. The SQLite
// implementation lives in internal/sqlite.
package store

import (
	"context"
	"errors"
	"time"
)

// ErrNotFound is what every read answers for a row that is not there: an
// email no account has, a session cookie no one holds, a slug no link owns.
var ErrNotFound = errors.New("store: not found")

// ErrDuplicate is what CreateUser answers for an email that already has an
// account and CreateLink for a slug that is already taken.
var ErrDuplicate = errors.New("store: already exists")

// ErrInvalid is what a method answers for an argument that cannot be
// stored: an empty email, hash, cookie, slug or target, a window of no
// days. The handlers answer 400 with it.
var ErrInvalid = errors.New("store: invalid argument")

// User is an account. PasswordHash is the bcrypt hash of the password and
// must never leave the API.
type User struct {
	ID           int64
	Email        string
	PasswordHash string
	CreatedAt    time.Time
}

// Session is a login: Cookie is the random value of the HttpOnly cookie,
// ExpiresAt when it stops being valid.
type Session struct {
	Cookie    string
	UserID    int64
	ExpiresAt time.Time
}

// Link is a shortened URL owned by a user. Slug is unique. TotalClicks is
// all the clicks ever recorded for it.
type Link struct {
	ID          int64
	UserID      int64
	Slug        string
	TargetURL   string
	CreatedAt   time.Time
	TotalClicks int64
}

// ClickStat is the clicks of one UTC day; Day is "YYYY-MM-DD".
type ClickStat struct {
	Day    string
	Clicks int64
}

// Store holds users, sessions and links. Every method takes a context and
// answers ErrNotFound or ErrDuplicate with the sentinel errors above; the
// callers switch on those instead of on driver errors.
type Store interface {
	// CreateUser stores a new account and returns it with its ID. It
	// answers ErrDuplicate when the email (compared case-insensitively)
	// already has one.
	CreateUser(ctx context.Context, email, passwordHash string) (*User, error)

	// GetUserByEmail answers ErrNotFound for an unknown email.
	GetUserByEmail(ctx context.Context, email string) (*User, error)

	// GetUserByID answers ErrNotFound for an unknown user.
	GetUserByID(ctx context.Context, id int64) (*User, error)

	// CreateSession stores a login whose cookie is not yet taken and
	// answers ErrDuplicate when it is.
	CreateSession(ctx context.Context, cookie string, userID int64, expiresAt time.Time) (*Session, error)

	// GetSession answers ErrNotFound for an unknown cookie, and also for
	// one whose ExpiresAt has passed.
	GetSession(ctx context.Context, cookie string) (*Session, error)

	// DeleteSession forgets a cookie; an unknown one is not an error.
	DeleteSession(ctx context.Context, cookie string) error

	// CreateLink answers ErrDuplicate for a slug another link already
	// holds.
	CreateLink(ctx context.Context, userID int64, slug, targetURL string) (*Link, error)

	// GetLinkBySlug answers ErrNotFound for an unknown slug.
	GetLinkBySlug(ctx context.Context, slug string) (*Link, error)

	// ListLinksByUser is newest first, each link with its total clicks.
	ListLinksByUser(ctx context.Context, userID int64) ([]Link, error)

	// DeleteLink removes the link holding slug and its clicks; an
	// unknown slug answers ErrNotFound.
	DeleteLink(ctx context.Context, slug string) error

	// RecordClick counts one click for the link, in total and for day
	// (a YYYY-MM-DD UTC day). An unknown slug answers ErrNotFound.
	RecordClick(ctx context.Context, slug string, day time.Time) error

	// GetClickStats answers the clicks per UTC day of the last days days
	// (today included), 0 for a day without clicks, oldest day first. An
	// unknown slug answers ErrNotFound.
	GetClickStats(ctx context.Context, slug string, days int) ([]ClickStat, error)

	// Close releases the storage.
	Close() error
}

