+// Package acceptance holds the spec's acceptance tests A1-A9: plain Go tests
+// over httptest and server.New, run by go test ./... like every other test.
+// Each one drives the whole app over HTTP, so it needs no store of its own:
+// server.New opens a temporary database when Config.DataDir stays empty.
+package acceptance
+
+import (
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/cookiejar"
+	"net/http/httptest"
+	"strings"
+	"testing"
+
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/server"
+)
+
+// client is a browser of the API: an http.Client that keeps the session
+// cookie the login sets and never follows a redirect, so a test reads the
+// 302 of a short link as the answer it is.
+func newClient(t *testing.T) *http.Client {
+	t.Helper()
+	jar, err := cookiejar.New(nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	c := &http.Client{Jar: jar}
+	c.CheckRedirect = func(*http.Request, []*http.Request) error {
+		return http.ErrUseLastResponse
+	}
+	return c
+}
+
+// newServer starts the app on a listener of its own, in a temporary data
+// directory, and returns it with a client that talks to nothing else.
+func newServer(t *testing.T) (*httptest.Server, *http.Client) {
+	t.Helper()
+	srv := httptest.NewServer(server.New(server.Config{DataDir: t.TempDir()}))
+	t.Cleanup(srv.Close)
+	return srv, newClient(t)
+}
+
+// do sends body to path with method and answers the response; the caller
+// closes its body.
+func do(t *testing.T, c *http.Client, method, url, body string) *http.Response {
+	t.Helper()
+	var r io.Reader
+	if body != "" {
+		r = strings.NewReader(body)
+	}
+	req, err := http.NewRequest(method, url, r)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if body != "" {
+		req.Header.Set("Content-Type", "application/json")
+	}
+	res, err := c.Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return res
+}
+
+// statusOf sends the request and answers only its status code, closing the
+// body so the connection is free for the next request.
+func statusOf(t *testing.T, c *http.Client, method, url, body string) int {
+	t.Helper()
+	res := do(t, c, method, url, body)
+	defer func() { _ = res.Body.Close() }()
+	return res.StatusCode
+}
+
+// get fetches a GET and answers its status with its body.
+func get(t *testing.T, c *http.Client, url string) (int, []byte) {
+	t.Helper()
+	res := do(t, c, http.MethodGet, url, "")
+	defer func() { _ = res.Body.Close() }()
+	b, err := io.ReadAll(res.Body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return res.StatusCode, b
+}
+
+// post sends body with POST and answers only the status code.
+func post(t *testing.T, c *http.Client, url, body string) int {
+	t.Helper()
+	return statusOf(t, c, http.MethodPost, url, body)
+}
+
+// jsonOf decodes the body of res into out.
+func jsonOf(t *testing.T, res *http.Response, out any) {
+	t.Helper()
+	b, err := io.ReadAll(res.Body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := json.Unmarshal(b, out); err != nil {
+		t.Fatalf("decoding %s: %v", b, err)
+	}
+}
+
+type meBody struct {
+	ID    int64  `json:"id"`
+	Email string `json:"email"`
+}
+
+type linkBody struct {
+	Slug      string `json:"slug"`
+	TargetURL string `json:"target_url"`
+	Clicks    int64  `json:"clicks"`
+}
+
+// jsonBody fetches a GET and decodes its JSON body into out, answering the
+// status code.
+func jsonBody(t *testing.T, c *http.Client, url string, out any) int {
+	t.Helper()
+	res := do(t, c, http.MethodGet, url, "")
+	defer func() { _ = res.Body.Close() }()
+	if err := json.NewDecoder(res.Body).Decode(out); err != nil {
+		t.Fatal(err)
+	}
+	return res.StatusCode
+}
+
+const longPassword = "correcthorsebatterystaple"
+
+// signup registers email and logs the new account in, so the returned client
+// holds its session cookie. It answers what GET /api/me names afterwards.
+func signup(t *testing.T, c *http.Client, baseURL, email string) meBody {
+	t.Helper()
+	res := do(t, c, http.MethodPost, baseURL+"/api/signup",
+		`{"email":"`+email+`","password":"`+longPassword+`"}`)
+	code := res.StatusCode
+	_, _ = io.Copy(io.Discard, res.Body)
+	_ = res.Body.Close()
+	if code != http.StatusCreated {
+		t.Fatalf("signup %s: status %d, want 201", email, code)
+	}
+
+	if code := statusOf(t, c, http.MethodPost, baseURL+"/api/login",
+		`{"email":"`+email+`","password":"`+longPassword+`"}`); code != http.StatusOK {
+		t.Fatalf("login %s: status %d, want 200", email, code)
+	}
+	var me meBody
+	jsonBody(t, c, baseURL+"/api/me", &me)
+	return me
+}
+
+// createLink shortens target for the logged-in client and answers its slug.
+func createLink(t *testing.T, c *http.Client, baseURL, slug, target string) string {
+	t.Helper()
+	body := `{"url":"` + target + `"}`
+	if slug != "" {
+		body = `{"url":"` + target + `","slug":"` + slug + `"}`
+	}
+	res := do(t, c, http.MethodPost, baseURL+"/api/links", body)
+	code := res.StatusCode
+	_, _ = io.Copy(io.Discard, res.Body)
+	_ = res.Body.Close()
+	if code != http.StatusCreated {
+		t.Fatalf("create link %q: status %d, want 201", slug, code)
+	}
+	var l linkBody
+	jsonBody(t, c, baseURL+"/api/links/"+slug, &l)
+	return l.Slug
+}

