// authedClient is a client that carries the session cookie of a login to
// every request, whatever scheme the server answers on: an http test server
// cannot keep a Secure cookie in a jar, because no browser would send one
// over an insecure connection either.
func authedClient(cookie string) *http.Client {
	c := &http.Client{}
	c.Transport = roundTripFunc(func(req *http.Request) (*http.Response, error) {
		req.AddCookie(&http.Cookie{Name: server.SessionCookie, Value: cookie})
		return http.DefaultTransport.RoundTrip(req)
	})
	return c
}

